use clap::{ArgGroup, Parser, Subcommand};
use language_lab::{invalid, Database, Filters, Result, Review};
use std::{io::Read, path::PathBuf};
#[derive(Parser)]
#[command(
    version,
    about = "Persistent learning records and calendar-based review scheduling"
)]
struct Cli {
    #[arg(long, global = true)]
    db: Option<PathBuf>,
    #[arg(long, global = true)]
    language: Option<String>,
    #[command(subcommand)]
    command: Command,
}
#[derive(Subcommand)]
enum Command {
    /// Create a new database without overwriting existing files.
    Init {
        path: PathBuf,
        #[arg(long)]
        timezone: String,
    },
    /// Read the current clock, languages, pinned records, due reviews and recent records.
    Context {
        #[arg(long, default_value_t = 20)]
        limit: usize,
    },
    /// Retrieve exact IDs, including historical records.
    Get {
        #[arg(required=true,num_args=1..)]
        ids: Vec<String>,
    },
    /// Query active or retired records.
    List {
        #[arg(long, conflicts_with = "retired")]
        due: bool,
        #[arg(long)]
        retired: bool,
        #[arg(long)]
        since: Option<String>,
        #[arg(long)]
        search: Option<String>,
        #[arg(long, default_value_t = 20)]
        limit: usize,
        #[arg(long)]
        cursor: Option<String>,
    },
    /// Atomically create, replace, split, merge or retire records from JSON. Use - for stdin.
    Replace {
        #[arg(long)]
        file: PathBuf,
    },
    /// Set or clear the pending review for active records.
    #[command(group(ArgGroup::new("mode").required(true).args(["in_days","on","clear"])))]
    Schedule {
        #[arg(required=true,num_args=1..)]
        ids: Vec<String>,
        #[arg(long)]
        in_days: Option<u64>,
        #[arg(long)]
        on: Option<String>,
        #[arg(long)]
        clear: bool,
    },
}

fn execute(cli: Cli) -> Result<serde_json::Value> {
    let now = chrono::Utc::now();
    if let Some(lang) = &cli.language {
        if lang.is_empty() {
            return Err(invalid("language must be nonempty"));
        }
    }
    if let Command::Init { path, timezone } = cli.command {
        return Database::init(&path, &timezone);
    }
    let path = cli.db.ok_or_else(|| invalid("--db is required"))?;
    let lang = cli.language.as_deref();
    if !matches!(cli.command, Command::Context { .. }) && lang.is_none() {
        return Err(invalid("--language is required"));
    }
    let mut db = Database::open(&path, now)?;
    match cli.command {
        Command::Context { limit } => db.context(lang, limit),
        Command::Get { ids } => db.get(lang.unwrap(), &ids),
        Command::List {
            due,
            retired,
            since,
            search,
            limit,
            cursor,
        } => db.list(
            lang.unwrap(),
            Filters {
                due,
                retired,
                since,
                search,
            },
            limit,
            cursor.as_deref(),
        ),
        Command::Replace { file } => {
            let mut input = String::new();
            if file.as_os_str() == "-" {
                std::io::stdin()
                    .read_to_string(&mut input)
                    .map_err(|e| invalid(e.to_string()))?;
            } else {
                input = std::fs::read_to_string(file).map_err(|e| {
                    if e.kind() == std::io::ErrorKind::InvalidData {
                        invalid(e.to_string())
                    } else {
                        e.into()
                    }
                })?;
            }
            let request = serde_json::from_str(&input).map_err(|e| invalid(e.to_string()))?;
            db.replace(lang.unwrap(), request)
        }
        Command::Schedule {
            ids,
            in_days,
            on,
            clear,
        } => db.schedule(
            lang.unwrap(),
            &ids,
            if clear {
                None
            } else {
                Some(Review { in_days, on })
            },
        ),
        Command::Init { .. } => unreachable!(),
    }
}

fn main() {
    let cli = match Cli::try_parse() {
        Ok(cli) => cli,
        Err(e)
            if matches!(
                e.kind(),
                clap::error::ErrorKind::DisplayHelp | clap::error::ErrorKind::DisplayVersion
            ) =>
        {
            print!("{e}");
            return;
        }
        Err(e) => fail(invalid(e.to_string())),
    };
    match execute(cli) {
        Ok(value) => println!("{value}"),
        Err(e) => fail(e),
    }
}

fn fail(error: language_lab::Error) -> ! {
    eprintln!("{}", serde_json::json!({"error":error}));
    std::process::exit(1)
}

pub fn open(path: &Path, now: DateTime<Utc>) -> Result<Self> {
    if !path.exists() {
        return Err(error("database_missing", "database does not exist"));
    }
    let conn = Connection::open_with_flags(path, OpenFlags::SQLITE_OPEN_READ_WRITE)?;
    conn.busy_timeout(std::time::Duration::from_secs(5))?;
    let metadata = || -> rusqlite::Result<(i64, String, String)> {
        conn.query_row("SELECT version,timezone,identity FROM metadata", [], |r| {
            Ok((r.get(0)?, r.get(1)?, r.get(2)?))
        })
    };
    let (version, zone, identity) =
        metadata().map_err(|e| error("database_invalid", e.to_string()))?;
    if version != 1 {
        return Err(error("schema_unsupported", "unsupported schema version"));
    }
    let timezone = zone
        .parse()
        .map_err(|_| error("database_invalid", "invalid stored timezone"))?;
    let check = || -> rusqlite::Result<()> {
        if conn.query_row("SELECT count(*) FROM metadata", [], |r| r.get::<_, i64>(0))? != 1
            || identity.is_empty()
        {
            return Err(rusqlite::Error::InvalidQuery);
        }
        conn.prepare("SELECT id,language,created_at,predecessors,content,pinned,review_on,retired_at FROM records")?;
        conn.prepare("SELECT timestamp,predecessors,successors,retired FROM events")?;
        Ok(())
    };
    check().map_err(|e| error("database_invalid", e.to_string()))?;
    Ok(Self {
        conn,
        timezone,
        identity,
        now,
    })
}

pub fn replace_with_ids(
    &mut self,
    lang: &str,
    request: Replacement,
    mut generator: impl FnMut() -> String,
) -> Result<Value> {
    language(lang)?;
    if request.ids.is_empty() && request.replacements.is_empty() {
        return Err(invalid("empty replacement"));
    }
    unique(&request.ids)?;
    let reviews = request
        .replacements
        .iter()
        .map(|e| e.review.as_ref().map(|r| self.resolve(r)).transpose())
        .collect::<Result<Vec<_>>>()?;
    let timestamp = self.now.to_rfc3339_opts(chrono::SecondsFormat::Nanos, true);
    let tx = self
        .conn
        .transaction_with_behavior(TransactionBehavior::Immediate)?;
    let old = active_records(&tx, lang, &request.ids)?;
    let retired: Vec<Value> = old
        .iter()
        .map(|r| json!({"id":r.id,"previous_review_on":r.review_on,"previous_pinned":r.pinned}))
        .collect();
    let mut created = Vec::new();
    let mut unscheduled = Vec::new();
    for (entry, review) in request.replacements.iter().zip(reviews.iter()) {
        let id = loop {
            let id = generator();
            if id.len() < 6
                || !id
                    .bytes()
                    .all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c))
            {
                return Err(invalid("invalid generated ID"));
            }
            if !tx.query_row(
                "SELECT EXISTS(SELECT 1 FROM records WHERE id=?1)",
                [&id],
                |r| r.get::<_, bool>(0),
            )? {
                break id;
            }
        };
        tx.execute(
            "INSERT INTO records VALUES (?1,?2,?3,?4,?5,?6,?7,NULL)",
            params![
                id,
                lang,
                timestamp,
                json!(request.ids).to_string(),
                entry.content.to_string(),
                entry.pinned,
                review
            ],
        )?;
        if review.is_none() {
            unscheduled.push(id.clone());
        }
        created.push(id);
    }
    for id in &request.ids {
        tx.execute(
            "UPDATE records SET retired_at=?1,review_on=NULL WHERE id=?2",
            params![timestamp, id],
        )?;
    }
    tx.execute(
        "INSERT INTO events VALUES (?1,?2,?3,?4)",
        params![
            timestamp,
            json!(request.ids).to_string(),
            json!(created).to_string(),
            json!(retired).to_string()
        ],
    )?;
    tx.commit()?;
    let mut reminders = Vec::new();
    if old.iter().any(|r| r.review_on.is_some()) && !unscheduled.is_empty() {
        reminders.push("Choose review dates for unscheduled successors.");
    }
    if old.iter().any(|r| r.pinned) && !created.is_empty() {
        reminders.push("Consider pinning successor records.");
    }
    Ok(
        json!({"created":created,"retired":retired,"needs_review_schedule":unscheduled,"reminders":reminders}),
    )
}

fn active_records(conn: &Connection, lang: &str, ids: &[String]) -> Result<Vec<Record>> {
    ids.iter()
        .map(|id| {
            let r = read_record(conn, lang, id)?;
            if r.retired_at.is_some() {
                Err(error("record_retired", format!("record {id} is retired")))
            } else {
                Ok(r)
            }
        })
        .collect()
}

fn read_record(conn: &Connection, lang: &str, id: &str) -> Result<Record> {
    let r = conn.query_row("SELECT id,language,created_at,predecessors,content,pinned,review_on,retired_at FROM records WHERE id=?1 AND language=?2",params![id,lang], |r| {
        let predecessors: String = r.get(3)?; let content: String = r.get(4)?;
        Ok((Record{id:r.get(0)?,language:r.get(1)?,created_at:r.get(2)?,replaces:Vec::new(),content:Value::Null,pinned:r.get(5)?,review_on:r.get(6)?,retired_at:r.get(7)?},predecessors,content))
    });
    match r {
        Ok((mut record, predecessors, content)) => {
            record.replaces = serde_json::from_str(&predecessors)
                .map_err(|_| error("database_invalid", "invalid stored predecessors"))?;
            record.content = parse_content(&content)
                .map_err(|_| error("database_invalid", "invalid stored content"))?;
            Ok(record)
        }
        Err(rusqlite::Error::QueryReturnedNoRows) => Err(error(
            "record_missing",
            format!("record {id} not found in selected language"),
        )),
        Err(e) => Err(e.into()),
    }
}

fn unique(ids: &[String]) -> Result<()> {
    if ids.iter().collect::<HashSet<_>>().len() != ids.len() {
        Err(invalid("duplicate IDs"))
    } else {
        Ok(())
    }
}

pub fn schedule(
    &mut self,
    lang: &str,
    ids: &[String],
    review: Option<Review>,
) -> Result<Value> {
    language(lang)?;
    if ids.is_empty() {
        return Err(invalid("at least one ID required"));
    }
    unique(ids)?;
    let resolved = review.as_ref().map(|r| self.resolve(r)).transpose()?;
    let tx = self
        .conn
        .transaction_with_behavior(TransactionBehavior::Immediate)?;
    active_records(&tx, lang, ids)?;
    for id in ids {
        tx.execute(
            "UPDATE records SET review_on=?1 WHERE id=?2",
            params![resolved, id],
        )?;
    }
    tx.commit()?;
    Ok(
        json!({"records":ids.iter().map(|id|json!({"id":id,"review_on":resolved})).collect::<Vec<_>>()}),
    )
}

fn subprocess_contract() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("db");
    let p = path.to_str().unwrap();
    let version = run(&["--version"], None);
    assert!(version.status.success());
    assert!(version.stderr.is_empty());
    assert_eq!(
        String::from_utf8(version.stdout).unwrap(),
        format!("language-lab {}\n", env!("CARGO_PKG_VERSION"))
    );
    for sub in [
        None,
        Some("init"),
        Some("context"),
        Some("get"),
        Some("list"),
        Some("replace"),
        Some("schedule"),
    ] {
        let mut args = vec![];
        if let Some(sub) = sub {
            args.push(sub);
        }
        args.push("--help");
        let out = run(&args, None);
        assert!(out.status.success());
        assert!(out.stderr.is_empty());
        let text = String::from_utf8(out.stdout).unwrap();
        assert!(text.contains("Usage:"));
        if sub.is_none() {
            for name in ["init", "context", "get", "list", "replace", "schedule"] {
                assert!(text.contains(name));
            }
        }
    }
    failure(run(&["--db", p, "context"], None), "database_missing");
    assert!(!path.exists());
    assert_eq!(
        success(run(&["init", p, "--timezone", "Europe/Berlin"], None)),
        json!({"database":p,"timezone":"Europe/Berlin"})
    );
    let baseline = std::fs::read(&path).unwrap();
    for args in [
        vec!["context"],
        vec!["--db", p, "list"],
        vec!["--db", p, "--language", "", "context"],
        vec!["--db", p, "--language", "el", "get"],
        vec!["--db", p, "--language", "el", "schedule", "--clear"],
        vec!["--db", p, "--language", "el", "schedule", "abcdef"],
        vec![
            "--db",
            p,
            "--language",
            "el",
            "schedule",
            "abcdef",
            "--clear",
            "--in-days",
            "1",
        ],
        vec!["--db", p, "context", "extra"],
        vec!["--db", p, "context", "--unknown"],
        vec![
            "--db",
            p,
            "--language",
            "el",
            "schedule",
            "abcdef",
            "--in-days",
            "-1",
        ],
        vec![
            "--db",
            p,
            "--language",
            "el",
            "schedule",
            "abcdef",
            "--in-days",
            "1.5",
        ],
        vec!["--db", p, "--language", "el", "list", "--due", "--retired"],
        vec!["--db", p, "--language", "el", "replace"],
    ] {
        failure(run(&args, None), "invalid_input");
        assert_eq!(std::fs::read(&path).unwrap(), baseline);
    }
    failure(
        run(&["init", p, "--timezone", "UTC"], None),
        "storage_error",
    );
    assert_eq!(std::fs::read(&path).unwrap(), baseline);
    let args = ["--db", p, "--language", "el", "replace", "--file", "-"];
    for input in [
        b"{}".as_slice(),
        b"{} {}",
        b"\xff",
        br#"{"ids":[],"replacements":[{}]}"#,
    ] {
        failure(run(&args, Some(input)), "invalid_input");
    }
    let created = success(run(
        &args,
        Some(br#"{"ids":[],"replacements":[{"content":null}]}"#),
    ));
    let id = created["created"][0].as_str().unwrap();
    let request = dir.path().join("request.json");
    std::fs::write(
        &request,
        r#"{"ids":[],"replacements":[{"content":{"custom":true}}]}"#,
    )
    .unwrap();
    success(run(
        &[
            "--db",
            p,
            "--language",
            "el",
            "replace",
            "--file",
            request.to_str().unwrap(),
        ],
        None,
    ));
    assert_eq!(
        success(run(&["--db", p, "--language", "el", "get", id, id], None))["records"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    success(run(
        &[
            "--db",
            p,
            "--language",
            "el",
            "schedule",
            id,
            "--in-days",
            "0",
        ],
        None,
    ));
    success(run(
        &[
            "--db",
            p,
            "--language",
            "el",
            "schedule",
            id,
            "--on",
            "2026-01-01",
        ],
        None,
    ));
    success(run(
        &["--db", p, "--language", "el", "schedule", id, "--clear"],
        None,
    ));
    assert_eq!(
        success(run(&["--db", p, "--language", "el", "list"], None))["records"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    success(run(&["--db", p, "context"], None));
    success(run(&["--db", p, "--language", "el", "context"], None));
    failure(
        run(&["--db", p, "--language", "fr", "get", id], None),
        "record_missing",
    );
}

fn invalid_requests_and_atomic_failures() {
    let (dir, mut db) = setup("UTC");
    let id = add(&mut db, "el", json!("a"));
    db.schedule("el", std::slice::from_ref(&id), review(2))
        .unwrap();
    let baseline = db.context(Some("el"), 20).unwrap();
    for bad in [
        json!({}),
        json!({"ids":[],"replacements":[{}]}),
        json!({"ids":[1],"replacements":[]}),
        json!({"ids":[],"replacements":[{"content":1,"pinned":null}]}),
        json!({"ids":[],"replacements":[{"content":1,"extra":true}]}),
        json!({"ids":[],"replacements":[],"extra":1}),
        json!({"ids":[],"replacements":[{"content":1,"review":{"in_days":-1}}]}),
        json!({"ids":[],"replacements":[{"content":1,"review":{"in_days":1.5}}]}),
        json!({"ids":[],"replacements":[{"content":1,"review":{"extra":3}}]}),
    ] {
        assert!(serde_json::from_value::<Replacement>(bad).is_err());
    }
    for bad in [
        json!({"ids":[],"replacements":[]}),
        json!({"ids":[id,id],"replacements":[]}),
        json!({"ids":[id,"missing"],"replacements":[{"content":1}]}),
        json!({"ids":[id],"replacements":[{"content":1,"review":{}}]}),
        json!({"ids":[id],"replacements":[{"content":1,"review":{"in_days":1,"on":"2026-01-01"}}]}),
    ] {
        assert!(db.replace("el", request(bad)).is_err());
        assert_eq!(db.context(Some("el"), 20).unwrap(), baseline);
    }
    assert_eq!(
        db.replace("fr", request(json!({"ids":[id],"replacements":[]})))
            .unwrap_err()
            .code,
        "record_missing"
    );
    let c = rusqlite::Connection::open(dir.path().join("db")).unwrap();
    c.execute_batch("CREATE TRIGGER fail_event BEFORE INSERT ON events BEGIN SELECT RAISE(ABORT,'simulated storage failure'); END;").unwrap();
    assert_eq!(
        db.replace(
            "el",
            request(json!({"ids":[id],"replacements":[{"content":"b"}]}))
        )
        .unwrap_err()
        .code,
        "storage_error"
    );
    assert_eq!(db.context(Some("el"), 20).unwrap(), baseline);
    c.execute_batch("DROP TRIGGER fail_event;").unwrap();
    db.replace("el", request(json!({"ids":[id],"replacements":[]})))
        .unwrap();
    assert_eq!(
        db.replace("el", request(json!({"ids":[id],"replacements":[]})))
            .unwrap_err()
            .code,
        "record_retired"
    );
}

fn storage_creation_validation_and_persistence() {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("db");
    assert_eq!(
        Database::open(&p, instant(NOW)).err().unwrap().code,
        "database_missing"
    );
    assert!(!p.exists());
    assert!(Database::init(&p, "bad/zone").is_err());
    assert!(!p.exists());
    let out = Database::init(&p, "Europe/Berlin").unwrap();
    assert_eq!(out, json!({"database":p,"timezone":"Europe/Berlin"}));
    let bytes = std::fs::read(&p).unwrap();
    assert!(bytes.starts_with(b"SQLite format 3\0"));
    assert_eq!(Database::init(&p, "UTC").unwrap_err().code, "storage_error");
    assert_eq!(bytes, std::fs::read(&p).unwrap());
    let mut db = Database::open(&p, instant(NOW)).unwrap();
    let id = add(&mut db, "el", json!("persisted"));
    drop(db);
    let db = Database::open(&p, instant(NOW)).unwrap();
    assert_eq!(record(&db, "el", &id)["content"], "persisted");
    drop(db);
    let c = rusqlite::Connection::open(&p).unwrap();
    c.execute("UPDATE metadata SET version=2", []).unwrap();
    drop(c);
    let bytes = std::fs::read(&p).unwrap();
    assert_eq!(
        Database::open(&p, instant(NOW)).err().unwrap().code,
        "schema_unsupported"
    );
    assert_eq!(bytes, std::fs::read(&p).unwrap());
    for contents in [b"not sqlite".as_slice(), b"".as_slice()] {
        let other = dir.path().join("invalid");
        std::fs::write(&other, contents).unwrap();
        assert_eq!(
            Database::open(&other, instant(NOW)).err().unwrap().code,
            "database_invalid"
        );
        assert_eq!(std::fs::read(&other).unwrap(), contents);
    }
    let other = dir.path().join("foreign");
    let c = rusqlite::Connection::open(&other).unwrap();
    c.execute("CREATE TABLE unrelated (x)", []).unwrap();
    drop(c);
    let bytes = std::fs::read(&other).unwrap();
    assert_eq!(
        Database::open(&other, instant(NOW)).err().unwrap().code,
        "database_invalid"
    );
    assert_eq!(std::fs::read(&other).unwrap(), bytes);
}

fn scheduling_atomic_and_passive_reads() {
    let (dir, mut db) = setup("UTC");
    let a = add(&mut db, "el", json!(1));
    let b = add(&mut db, "el", json!(2));
    let foreign = add(&mut db, "fr", json!(3));
    let ids = vec![b.clone(), a.clone()];
    let out = db.schedule("el", &ids, review(0)).unwrap();
    assert_eq!(
        out["records"],
        json!([{"id":b,"review_on":"2026-10-17"},{"id":a,"review_on":"2026-10-17"}])
    );
    let before = record(&db, "el", &a);
    for ids in [
        vec![],
        vec![a.clone(), a.clone()],
        vec![a.clone(), "missing".into()],
        vec![a.clone(), foreign],
    ] {
        assert!(db.schedule("el", &ids, review(5)).is_err());
        assert_eq!(record(&db, "el", &a), before);
    }
    let c = rusqlite::Connection::open(dir.path().join("db")).unwrap();
    c.execute_batch(&format!("CREATE TRIGGER fail_update BEFORE UPDATE ON records WHEN OLD.id='{a}' BEGIN SELECT RAISE(ABORT,'failure'); END;")).unwrap();
    assert_eq!(
        db.schedule("el", &ids, review(5)).unwrap_err().code,
        "storage_error"
    );
    assert_eq!(record(&db, "el", &b)["review_on"], "2026-10-17");
    c.execute_batch("DROP TRIGGER fail_update;").unwrap();
    db.context(Some("el"), 1).unwrap();
    db.list(
        "el",
        Filters {
            due: true,
            ..Default::default()
        },
        20,
        None,
    )
    .unwrap();
    add(&mut db, "el", json!({"kind":"practice","related_to":[a]}));
    assert_eq!(record(&db, "el", &a), before);
    db.replace("el", request(json!({"ids":[b],"replacements":[]})))
        .unwrap();
    assert_eq!(
        db.schedule("el", &[a.clone(), b], None).unwrap_err().code,
        "record_retired"
    );
    assert_eq!(record(&db, "el", &a), before);
}

use chrono::{DateTime, Utc};
use language_lab::{Database, Filters, Replacement, Review};
use serde_json::{json, Value};
use tempfile::TempDir;
fn instant(s: &str) -> DateTime<Utc> {
    s.parse().unwrap()
}
const NOW: &str = "2026-10-17T12:00:00Z";
fn setup(zone: &str) -> (TempDir, Database) {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("db");
    Database::init(&p, zone).unwrap();
    let db = Database::open(&p, instant(NOW)).unwrap();
    (dir, db)
}
fn request(v: Value) -> Replacement {
    serde_json::from_value(v).unwrap()
}
fn add(db: &mut Database, lang: &str, content: Value) -> String {
    db.replace(
        lang,
        request(json!({"ids":[],"replacements":[{"content":content}]})),
    )
    .unwrap()["created"][0]
        .as_str()
        .unwrap()
        .into()
}
fn record(db: &Database, lang: &str, id: &str) -> Value {
    db.get(lang, &[id.into()]).unwrap()["records"][0].clone()
}
fn review(days: u64) -> Option<Review> {
    Some(Review {
        in_days: Some(days),
        on: None,
    })
}

use serde_json::{json, Value};
use std::{
    io::Write,
    process::{Command, Output, Stdio},
};
fn run(args: &[&str], input: Option<&[u8]>) -> Output {
    let mut c = Command::new(env!("CARGO_BIN_EXE_language-lab"));
    c.args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = c.spawn().unwrap();
    if let Some(input) = input {
        child.stdin.take().unwrap().write_all(input).unwrap();
    }
    child.wait_with_output().unwrap()
}
fn success(out: Output) -> Value {
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(out.stderr.is_empty());
    serde_json::from_slice(&out.stdout).unwrap()
}
fn failure(out: Output, code: &str) {
    assert!(!out.status.success());
    assert!(out.stdout.is_empty());
    let v: Value = serde_json::from_slice(&out.stderr).unwrap();
    assert_eq!(v["error"]["code"], code);
    assert!(v["error"]["message"].is_string());
}
